def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    marker = next((v for v in range(10) if v != bg and any(v in row for row in grid)), None)
    if marker is None:
        return [row[:] for row in grid]

    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    fill = 2

    # Complete interrupted marker lines along the object's outer boundary.
    for r in (r0, r1):
        if any(grid[r][c] == marker for c in range(c0, c1 + 1)):
            for c in range(c0, c1 + 1):
                if grid[r][c] == bg:
                    out[r][c] = fill
    for c in (c0, c1):
        if any(grid[r][c] == marker for r in range(r0, r1 + 1)):
            for r in range(r0, r1 + 1):
                if grid[r][c] == bg:
                    out[r][c] = fill

    # Bridge gaps on sufficiently populated interior marker lines.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] == marker]
        if len(cols) >= 4:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = fill
    for c in range(c0 + 1, c1):
        rows = [r for r in range(r0, r1 + 1) if grid[r][c] == marker]
